-- Nifty 100 Data Warehouse Seed File
-- Connect to bluestock_dw and execute this file

-- Star Schema for Nifty 100 Financial Intelligence

-- 1. Dimension Tables cc 
CREATE TABLE IF NOT EXISTS dim_company (
    symbol VARCHAR(20) PRIMARY KEY,
    company_name VARCHAR(255) NOT NULL,
    sector VARCHAR(100),
    sub_sector VARCHAR(100),
    company_logo TEXT,
    website TEXT,
    nse_url TEXT,
    bse_url TEXT,
    face_value DECIMAL(10, 2),
    book_value DECIMAL(10, 2),
    about_company TEXT
);

CREATE TABLE IF NOT EXISTS dim_year (
    year_id SERIAL PRIMARY KEY,
    year_label VARCHAR(20) UNIQUE NOT NULL,
    fiscal_year INT,
    quarter VARCHAR(2),
    is_ttm BOOLEAN DEFAULT FALSE,
    is_half_year BOOLEAN DEFAULT FALSE,
    sort_order INT
);

CREATE TABLE IF NOT EXISTS dim_sector (
    sector_id SERIAL PRIMARY KEY,
    sector_name VARCHAR(100) UNIQUE NOT NULL,
    sector_code VARCHAR(20),
    description TEXT
);

CREATE TABLE IF NOT EXISTS dim_health_label (
    label_id SERIAL PRIMARY KEY,
    label_name VARCHAR(50) UNIQUE NOT NULL, -- EXCELLENT/GOOD/AVERAGE/WEAK/POOR
    min_score INT,
    max_score INT,
    color_hex VARCHAR(7)
);

-- 2. Fact Tables
CREATE TABLE IF NOT EXISTS fact_profit_loss (
    id SERIAL PRIMARY KEY,
    symbol VARCHAR(20) REFERENCES dim_company(symbol),
    year_label VARCHAR(20), -- We'll join on year_label for simplicity or use year_id
    sales DECIMAL(15, 2),
    expenses DECIMAL(15, 2),
    operating_profit DECIMAL(15, 2),
    opm_pct DECIMAL(10, 2),
    other_income DECIMAL(15, 2),
    interest DECIMAL(15, 2),
    depreciation DECIMAL(15, 2),
    profit_before_tax DECIMAL(15, 2),
    tax_pct DECIMAL(10, 2),
    net_profit DECIMAL(15, 2),
    eps DECIMAL(15, 2),
    dividend_payout_pct DECIMAL(10, 2),
    net_profit_margin_pct DECIMAL(10, 2),
    expense_ratio_pct DECIMAL(10, 2),
    interest_coverage DECIMAL(10, 2),
    UNIQUE(symbol, year_label)
);

CREATE TABLE IF NOT EXISTS fact_balance_sheet (
    id SERIAL PRIMARY KEY,
    symbol VARCHAR(20) REFERENCES dim_company(symbol),
    year_label VARCHAR(20),
    equity_capital DECIMAL(15, 2),
    reserves DECIMAL(15, 2),
    borrowings DECIMAL(15, 2),
    other_liabilities DECIMAL(15, 2),
    total_liabilities DECIMAL(15, 2),
    fixed_assets DECIMAL(15, 2),
    cwip DECIMAL(15, 2),
    investments DECIMAL(15, 2),
    other_assets DECIMAL(15, 2),
    total_assets DECIMAL(15, 2),
    debt_to_equity DECIMAL(10, 4),
    equity_ratio DECIMAL(10, 4),
    UNIQUE(symbol, year_label)
);

CREATE TABLE IF NOT EXISTS fact_cash_flow (
    id SERIAL PRIMARY KEY,
    symbol VARCHAR(20) REFERENCES dim_company(symbol),
    year_label VARCHAR(20),
    operating_activity DECIMAL(15, 2),
    investing_activity DECIMAL(15, 2),
    financing_activity DECIMAL(15, 2),
    net_cash_flow DECIMAL(15, 2),
    free_cash_flow DECIMAL(15, 2),
    UNIQUE(symbol, year_label)
);

CREATE TABLE IF NOT EXISTS fact_analysis (
    id SERIAL PRIMARY KEY,
    symbol VARCHAR(20) REFERENCES dim_company(symbol),
    period_label VARCHAR(10), -- 10Y/5Y/3Y/TTM
    compounded_sales_growth_pct DECIMAL(10, 2),
    compounded_profit_growth_pct DECIMAL(10, 2),
    stock_price_cagr_pct DECIMAL(10, 2),
    roe_pct DECIMAL(10, 2),
    UNIQUE(symbol, period_label)
);

CREATE TABLE IF NOT EXISTS fact_ml_scores (
    id SERIAL PRIMARY KEY,
    symbol VARCHAR(20) REFERENCES dim_company(symbol),
    computed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    overall_score INT,
    profitability_score INT,
    growth_score INT,
    leverage_score INT,
    cashflow_score INT,
    dividend_score INT,
    trend_score INT,
    health_label VARCHAR(50)
);

CREATE TABLE IF NOT EXISTS fact_pros_cons (
    id SERIAL PRIMARY KEY,
    symbol VARCHAR(20) REFERENCES dim_company(symbol),
    is_pro BOOLEAN,
    category VARCHAR(50),
    text TEXT,
    source VARCHAR(50) DEFAULT 'MANUAL', -- MANUAL/ML
    confidence DECIMAL(5, 2),
    generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


