INSERT INTO dim_company (symbol, company_name, sector, sub_sector, company_logo, website, nse_url, bse_url, face_value, book_value, about_company) VALUES ('TATAMOTORS', 'Tata Motors Ltd', 'nan', 'nan', 'https://mkt.in/static/mkt-icons/nifty100/TATAMOTORS.png', 'https://www.tatamotors.com/', 'https://www.nseindia.com/get-quotes/equity?symbol=TATAMOTORS', 'https://www.bseindia.com/stock-share-price/tata-motors-ltd/TATAMOTORS/500570/', 2.0, 275.0, 'Tata Motors Group is a leading global automobile manufacturer. Part of the illustrious multi-national conglomerate, the Tata group, it offers a wide and diverse portfolio of cars, sports utility vehicles, trucks, buses and defence vehicles to the world.
